package com.steven.assets.service.srpp.settings;
import com.steven.assets.dto.SrppClaudeAuthDto;import org.junit.jupiter.api.Test;import java.net.URLEncoder;import java.nio.charset.StandardCharsets;import java.util.*;import static org.assertj.core.api.Assertions.*;
class SrppClaudeAuthDtoTest {
 String url(){Map<String,String>q=new LinkedHashMap<>();q.put("code","true");q.put("response_type","code");q.put("redirect_uri","https://platform.claude.com/oauth/code/callback");q.put("client_id","9d1c250a-e61b-44d9-88ed-5944d1962f5e");q.put("scope","org:create_api_key user:profile user:inference user:sessions:claude_code user:mcp_servers user:file_upload user:plugins user:privacy_consents:write");q.put("code_challenge","a".repeat(43));q.put("code_challenge_method","S256");q.put("state","b".repeat(32));return "https://claude.com/cai/oauth/authorize?"+q.entrySet().stream().map(e->e.getKey()+"="+URLEncoder.encode(e.getValue(),StandardCharsets.UTF_8)).collect(java.util.stream.Collectors.joining("&"));}
 @Test void onlyExactNativeOfficialUrlAndAllEightScopesAreAccepted(){String u=url();assertThat(SrppClaudeAuthDto.official(u)).isTrue();for(String bad:List.of(u.replace("claude.com/","claude.ai/"),u.replace("https://claude.com/","https://attacker@claude.com/"),u.replace("https://claude.com/","https://claude.com:444/"),u+"&state=duplicate",u+"&login_hint=private",u+"#fragment",u.replace("org%3Acreate_api_key+","")))assertThat(SrppClaudeAuthDto.official(bad)).isFalse();}
 @Test void schemaCoercionsAndUnknownFieldsRejected(){assertThatThrownBy(()->SrppClaudeAuthDto.local(SrppClaudeAuthDto.parse("{\"schemaVersion\":\"1\",\"toolId\":\"claude\",\"loginState\":\"VALID\",\"expiresAt\":\"2099-11-16T00:00:00Z\",\"code\":null}"))).isInstanceOf(IllegalArgumentException.class);assertThatThrownBy(()->SrppClaudeAuthDto.local(SrppClaudeAuthDto.parse("{\"schemaVersion\":1,\"toolId\":\"claude\",\"loginState\":\"VALID\",\"expiresAt\":\"2099-11-16T00:00:00Z\",\"code\":null,\"token\":\"SECRET\"}"))).hasMessageNotContaining("SECRET");}
 @Test void terminalFlowCannotCarryUrlAndSensitiveToStringIsRedacted(){var n=SrppClaudeAuthDto.JSON.createObjectNode().put("schemaVersion",1).put("flowId","f".repeat(43)).put("toolId","claude").put("status","WAITING_FOR_CODE").put("authorizationUrl",url()).put("expiresAt","2026-11-16T00:00:00Z").putNull("code");assertThat(SrppClaudeAuthDto.flow(n).toString()).doesNotContain("https://","code_challenge");n.put("status","SUCCEEDED");assertThatThrownBy(()->SrppClaudeAuthDto.flow(n)).isInstanceOf(IllegalArgumentException.class);}
 @Test void malformedSuccessAndLocalStateTuplesAreRejected(){var local=SrppClaudeAuthDto.JSON.createObjectNode().put("schemaVersion",1).put("toolId","claude").put("loginState","VALID").put("expiresAt","2099-11-16T00:00:00Z").putNull("code");assertThat(SrppClaudeAuthDto.local(local).loginState()).isEqualTo("VALID");assertThat(SrppClaudeAuthDto.local(local).expiresAt()).isInstanceOf(java.time.Instant.class);assertThat(SrppClaudeAuthDto.JSON.valueToTree(SrppClaudeAuthDto.local(local)).path("expiresAt").textValue()).isEqualTo("2099-11-16T00:00:00Z");for(String state:List.of("EXPIRED","AUTHENTICATING","REQUIRED","UNKNOWN")){local.put("loginState",state);assertThatThrownBy(()->SrppClaudeAuthDto.local(local)).isInstanceOf(IllegalArgumentException.class);}local.put("loginState","VALID").put("expiresAt","2020-01-01T00:00:00Z");assertThatThrownBy(()->SrppClaudeAuthDto.local(local)).isInstanceOf(IllegalArgumentException.class);local.put("expiresAt","2099-01-01T00:00:00Z").put("code","AI_AUTH_REQUIRED");assertThatThrownBy(()->SrppClaudeAuthDto.local(local)).isInstanceOf(IllegalArgumentException.class);
 var flow=SrppClaudeAuthDto.JSON.createObjectNode().put("schemaVersion",1).put("flowId","f".repeat(43)).put("toolId","claude").put("status","SUCCEEDED").putNull("authorizationUrl").put("expiresAt","2099-01-01T00:00:00Z").put("code","AUTH_FAILED");assertThatThrownBy(()->SrppClaudeAuthDto.flow(flow)).isInstanceOf(IllegalArgumentException.class);flow.putNull("code");assertThat(SrppClaudeAuthDto.flow(flow).status()).isEqualTo("SUCCEEDED");for(String state:List.of("WAITING_FOR_CODE","FAILED","EXPIRED")){flow.put("status",state);assertThatThrownBy(()->SrppClaudeAuthDto.flow(flow)).isInstanceOf(IllegalArgumentException.class);}flow.put("status","EXPIRED").put("code","AUTH_FAILED");assertThatThrownBy(()->SrppClaudeAuthDto.flow(flow)).isInstanceOf(IllegalArgumentException.class);flow.put("code","AUTH_TIMEOUT");assertThat(SrppClaudeAuthDto.flow(flow).status()).isEqualTo("EXPIRED");}
}
